text:
{
  "questions": [
    {
      "n": 1,
      "start": "Hat der Stadtrat Kenntnis von der geplanten Aufteilung",
      "end": "der Ladenlokale im Zürisee Center Wädenswil?"
    },
    {
      "n": 2,
      "start": "Wie gedenkt der Stadtrat beim geplanten Mix der Ladenlokale",
      "end": "seinen Einfluss geltend zu machen, damit die Sonderbauvorschrift \"Hintere Rüti\" eingehalten wird?"
    },
    {
      "n": 3,
      "start": "Mit dem Migros-Super-/Verbrauchsmarkt. Sind die erlaubten 10% der",
      "end": "Verkaufsfläche ohne Beschränkung bereits mehr als ausgeschöpft."
    },
    {
      "n": 4,
      "start": "Ausserdem sind sich die Verfasser der Anfrage nicht sicher, in welche",
      "end": "Kategorie die Güter des Migros-SportXX einzuteilen sind."
    },
    {
      "n": 5,
      "start": "Den Verfassern der Anfrage ist es ein wichtiges Anliegen, dass die Versorgung",
      "end": "im Zentrum von Wädenswil mit Gütern des alltäglichen Bedarfs weiterhin gesichert ist"
    },
    {
      "n": 6,
      "start": "Die Verfasser der Anfrage sehen im heute geplanten Ladenmix des ZüriseeCenter",
      "end": "Wädenswil nicht mehr ein Fachmarktprojekt, sondern viel eher ein Shopping Center."
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Die genaue Aufteilung liegt der Baubewilligung vom",
      "end": "16. August 2011 zugrunde."
    },
    {
      "n": 2,
      "start": "Die mit der Baubewilligung bewilligten Flächen werden periodisch kontrolliert.",
      "end": "periodisch kontrolliert."
    },
    {
      "n": 3,
      "start": "Der Betreiber des Zürisee-Centers muss sich an die Vorgaben der",
      "end": "Baubewilligung halten, diese werden periodisch kontrolliert."
    },
    {
      "n": 4,
      "start": "Sportartikel fallen nicht unter die Kategorie \"Güter des täglichen Bedarfs\".",
      "end": "Zuständig zur Beurteilung ist die Baubehörde."
    },
    {
      "n": 5,
      "start": "Auch dem Stadtrat ist es ein Anliegen, dass das Versorgungsangebot im",
      "end": "Zentrum möglichst vielfältig und attraktiv bleibt."
    },
    {
      "n": 6,
      "start": "Die Sonderbauvorschriften \"Hintere Rüti\" sind vom Gemeinderat am 14. Mai",
      "end": "2001 beschlossen worden. Baukommission und Stadtrat haben sich an diese Vorgaben zu halten."
    }
  ],
  "submitter": "Adrian Stucki und Heinz Wiher",
  "co_signatories": ["Tobias Mani"],
  "recommendation": "none",
  "reasoning": null
}
